import{_ as a,c as r,o as n,ae as o}from"./chunks/framework.Dh1jimFm.js";const t="/assets/2_TRes-NeRF.Df3k0Fv8.png",s="/assets/3_IOVS4NeRF.BHew8Uae.png",u=JSON.parse('{"title":"我发表的论文","description":"","frontmatter":{},"headers":[],"relativePath":"2_articles/1_my_paper.md","filePath":"2_articles/1_my_paper.md","lastUpdated":1747291178000}'),i={name:"2_articles/1_my_paper.md"};function l(c,e,p,d,m,_){return n(),r("div",null,e[0]||(e[0]=[o('<h1 id="我发表的论文" tabindex="-1">我发表的论文 <a class="header-anchor" href="#我发表的论文" aria-label="Permalink to &quot;我发表的论文&quot;">​</a></h1><h2 id="📌1-三维重建" tabindex="-1">📌1. 三维重建 <a class="header-anchor" href="#📌1-三维重建" aria-label="Permalink to &quot;📌1. 三维重建&quot;">​</a></h2><hr><h3 id="📝-tres-nerf-temporal-residual-neural-radiance-fields-for-monocular-video-dynamic-human-body-reconstruction" tabindex="-1">📝 TRes-NeRF:Temporal residual neural radiance fields for monocular video dynamic human body reconstruction <a class="header-anchor" href="#📝-tres-nerf-temporal-residual-neural-radiance-fields-for-monocular-video-dynamic-human-body-reconstruction" aria-label="Permalink to &quot;📝 TRes-NeRF:Temporal residual neural radiance fields for monocular video dynamic human body reconstruction&quot;">​</a></h3><p><strong>Tianle Du</strong>, Xiaolong Xie, Jie Wang, Wei Li* et al. -- <strong>Accept: 2024-06-18</strong></p><p><strong>简介：</strong> 为解决神经辐射场在动态场景中人体重建时的计算资源耗费问题，本文提出了时间残差神经辐射场的方法TRes-NeRF，构建了一个基于MLP的时间残差层，并贡献了一种减少可训练参数与加速渲染的集成方法。与最优方法相比，该网络在保持了相近的精度下时间效率提升了近780倍，实现了高质量的人体动态重建与新姿势合成。</p><p><strong>发表刊物：</strong> SCI四区，<strong>Journal of Electronic Imagining</strong>，IF=1.5</p><p><strong>PDF链接：</strong><a href="../3_my_paper/0_TRes-NeRF.pdf">点击查看 PDF📄</a></p><p><strong>关于论文的故事：</strong> 这是我人生中发表的第一篇学术论文、本科第一篇SCI、第一篇一作论文，简单来说，是我学术生涯的处女作，踏入学术大门的第一步。这篇工作花了我半年的时间，最后也仅仅发表在了四区刊物上，让我感觉到自己并没有科研天赋，但这篇论文帮助我保研进入了985高校强组，以及人生中的第一次算法岗实习，让我对科研有了更深的理解，也彻底踏入了计算机视觉这条道路。 <img src="'+t+'" alt="TRes-NeRF"></p><hr><h3 id="📝-iovs4nerf-incremental-optimal-view-selection-for-large-scale-nerfs" tabindex="-1">📝 IOVS4NeRF: Incremental Optimal View Selection for Large-Scale NeRFs <a class="header-anchor" href="#📝-iovs4nerf-incremental-optimal-view-selection-for-large-scale-nerfs" aria-label="Permalink to &quot;📝 IOVS4NeRF: Incremental Optimal View Selection for Large-Scale NeRFs&quot;">​</a></h3><p>Jingpeng Xie, Shiyu Tan, Yuanlei Wang, <strong>Tianle Du</strong> et al. -- <strong>Accept: 2024-12-21</strong></p><p><strong>简介：</strong> 大规模的神经辐射场（NeRF）重建通常受限于对大量图像数据和高计算资源的需求。本文提出了IOVS4NeRF框架，采用基于不确定性的增量式最优视角选择策略，适用于多种NeRF实现。该方法结合渲染和位置不确定性，选择最具信息量的视角，逐步优化场景重建。实验表明，该方法可在资源有限的情况下实现高质量的NeRF重建，适用于大规模场景应用。</p><p><strong>发表刊物：</strong> CCF-B，ICASSP 2024</p><p><strong>PDF链接：</strong><a href="../3_my_paper/1_IOVS4NeRF.pdf">点击查看 PDF📄</a></p><p><strong>关于论文的故事：</strong> 这篇工作是鹏哥研究生的第一篇论文，也是我的第一篇B会，因为没干什么活，所以就挂个名~</p><p><img src="'+s+'" alt="IOVS4NeRF"></p>',17)]))}const f=a(i,[["render",l]]);export{u as __pageData,f as default};
